    }

    // Each card's columns, packed by the code the decode shard path already uses, at the rank each card holds in
    // THIS pair.  `qsa_pair_prepare` derives rank from the device it is given and refuses a mismatch, so a
    // swapped pair fails here instead of silently reducing two copies of one card's half.
    const core::QsaHeadShard lead_sh = core::qsa_pair_shard(g.n_head, g.n_head_kv, lead_heads, /*rank*/ 0);
    const core::QsaHeadShard peer_sh = core::qsa_pair_shard(g.n_head, g.n_head_kv, lead_heads, /*rank*/ 1);
    if (!core::qsa_pair_prepare(qs.lead_cols, wt, g, lead_sh, qs.pair, lead_dev, P.dev, lb, le, err)) {
        err = "prefill peer: the lead's attn_output columns did not build: " + err;
        qs.pair.close();
        return false;
    }
    if (!core::qsa_pair_prepare(qs.peer_cols, wt, g, peer_sh, qs.pair, P.dev, lead_dev, lb, le, err)) {
        err = "prefill peer: the partner's attn_output columns did not build: " + err;
        core::qsa_pair_free(qs.lead_cols);
        qs.pair.close();
        return false;
    }

    // Both sets exist, on the same layers, for the whole stage.  Checked rather than trusted because the two
    // prepares can disagree: the pack decides per tensor, and `attn_q` already taught this project that "it is
    // uniform across the QSA layers" is the assumption that was wrong.
    int64_t built = 0;
    for (int64_t l = lb; l < le; ++l) {
        if (!core::is_qsa_layer(g, l)) continue;
        if (!qs.lead_cols.o_cols[(size_t) l].ok || !qs.peer_cols.o_cols[(size_t) l].ok) {
            err = "prefill peer: layer " + std::to_string(l) + " is missing its packed attn_output columns on one "
                  "of the pair's cards";
            core::qsa_pair_free(qs.lead_cols);
            core::qsa_pair_free(qs.peer_cols);
            qs.pair.close();
            return false;
        }
        ++built;
    }
    if (built == 0) { err = "prefill peer: the stage holds no QSA layer, so there is nothing to reduce"; return false; }
    if (qs.lead_cols.o_cols.size() != (size_t) g.n_layers || qs.peer_cols.o_cols.size() != (size_t) g.n_layers) {
        err = "prefill peer: the packed columns are not indexed by absolute layer number";
        return false;
    }
    // The columns reduce; these are what the arm PROJECTS with.  Filled here, once, so a QSA layer's arm never
    // touches the link for weight and the ledger's per-layer traffic stays the bytes it says it is.
    if (!peer_qsa_resident_up(P, wt, lead_dev, lb, le, err)) {
        core::qsa_pair_free(qs.lead_cols);
        core::qsa_pair_free(qs.peer_cols);
        qs.pair.close();
        return false;
    }
    basalt::log::info("basalt prefill",
                      "peer prompt-attention pair CUDA%d+CUDA%d open, staging %lld floats; attn_output columns "
                      "packed on both cards over %lld QSA layers (lead %d/%d, partner %d/%d heads; %s, %d o_proj "
                      "staging set%s, %d collective staging set%s)",
                      lead_dev, P.dev, (long long) elems, (long long) built,
                      (int) lead_sh.nq(), (int) g.n_head, (int) peer_sh.nq(), (int) g.n_head,
                      P.qsa.pipeline >= 2 ? "pipelined" : "serialized", P.qsa.span.staging_sets,
                      P.qsa.span.staging_sets == 1 ? "" : "s", qs.pair.sets(), qs.pair.sets() == 1 ? "" : "s");
    return true;
}

/// The partner's resident projections, copied off the lead's card ONCE at boot: its shard's rows of `attn_q`, its
/// KV head's rows of `attn_k` and `attn_v`, and the four RMS norms those projections and the indexer read.  The
/// RUN 25 ruling put them resident so no QSA layer moves weight bytes across the link; the allocation is the
/// walk's (`peer_qsa_layout`), and this is the copy that makes those buffers mean something - without it the arm
/// multiplies whatever `cudaMalloc` left in them, which is a plausible token rather than a fault.
///
/// Every copy is checked against the figure the span was PRICED from, per layer rather than once: the sizer reads
/// one QSA layer and multiplies, so a pack that changed a projection's type or row width between layers would
/// otherwise copy a wider row into a buffer sized for a narrower one.  A pack that serves the tensor from its GGUF
/// section keeps it only as a native image, which is the form copied here and the form `Gemm::native` reads.
bool peer_qsa_resident_up(PeerPrefill& P, const core::WeightTable& wt, int lead_dev, int64_t lb, int64_t le,
                          std::string& err) {
    PeerPrefill::Qsa& qs = P.qsa;
    const Prefill::PeerQsaSpan& sp = qs.span;
    if (!qs.live || !sp.on || sp.g == nullptr || !sp.heads.ok()) {
        err = "prefill peer: the prompt-attention arm is not live, so it has no projections to fill";
        return false;
    }
    if (!P.p2p) {
        err = "prefill peer: the resident projections need peer access between CUDA" + std::to_string(lead_dev) +
              "
